/* thumbnail sai de graça, sem API e sem cota */
/* ============================================================
   DE ONDE VEM A IMAGEM E O VÍDEO

   Extensão de privacidade costuma bloquear img.youtube.com e
   www.youtube.com por serem domínios de rastreamento, mas
   deixa passar i.ytimg.com e youtube-nocookie.com, que são as
   versões sem cookie. Começamos por essas.
   ============================================================ */
export const SERVIDORES_CAPA = [
  (id, t) => `https://i.ytimg.com/vi/${id}/${t}default.jpg`,
  (id, t) => `https://i9.ytimg.com/vi/${id}/${t}default.jpg`,
  (id, t) => `https://img.youtube.com/vi/${id}/${t}default.jpg`,
];

export const capa = (id, tamanho = 'hq', servidor = 0) =>
  SERVIDORES_CAPA[Math.min(servidor, SERVIDORES_CAPA.length - 1)](id, tamanho);

/* o player sem cookie passa por onde o normal não passa */
export const embed = (id, params = '') =>
  `https://www.youtube-nocookie.com/embed/${id}?rel=0&modestbranding=1&playsinline=1${params}`;

export const linkAula = (id) => `https://www.youtube.com/watch?v=${id}`;

export function duracaoTexto(seg) {
  const m = Math.floor(seg / 60);
  const s = seg % 60;
  if (m >= 60) return `${Math.floor(m / 60)}h${String(m % 60).padStart(2, '0')}`;
  return m > 0 ? `${m}:${String(s).padStart(2, '0')}` : `${s}s`;
}

